"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisCtaContent } from "./components/cta-sections/content";
import View7 from "./components/cta-sections/variants/08-terminal";
const views={"terminal":View7};
export type { ArtemisCtaContent, ArtemisCtaImage, ArtemisCtaLink, ArtemisCtaQuestion, ArtemisCtaStat } from "./components/cta-sections/content";
export interface ArtemisCtaSectionsProps{className?:string;variant?:"terminal"; /** The words on the CTA section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisCtaContent>; }
export function ArtemisCtaSections({className,variant="terminal",content}:ArtemisCtaSectionsProps){const View=views[variant];return <ArtemisScope className={className}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisCtaLink {
  label: string;
  href: string;
}

/** A picture, and the words that describe it. */
export interface ArtemisCtaImage {
  src: string;
  /** What the picture shows; empty for a purely decorative one. */
  alt: string;
}

/** A figure with a short label under it. */
export interface ArtemisCtaStat {
  /** The figure as text, such as "120" or "4.9". Its digits roll into place. */
  value: string;
  /** Shown right after the figure, such as "K+" or "/5". */
  suffix?: string;
  /** What the figure counts. */
  label: string;
}

/** A question and its answer. */
export interface ArtemisCtaQuestion {
  question: string;
  answer: string;
  /** A short id, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
}

/** The words on an Artemis CTA section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisCtaContent {
  /** The short line above the heading. sunflower, product-window, proof-orbit, shade-panel, glow and terminal. */
  badge?: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's second part. glow shows it on a line of its own in a muted tone; faq, terminal and split start a new line for it; the other layouts run it on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The main button. All layouts. */
  cta: ArtemisCtaLink;
  /** A second button. floating-gallery, portrait-frame, glow, terminal and split. */
  secondaryCta?: ArtemisCtaLink;
  /** A quiet text link under the buttons. split. */
  link?: ArtemisCtaLink;
  /** A short line near the buttons. sunflower, portrait-frame, proof-orbit and glow. */
  note?: string;
  /** The picture beside the words. portrait-frame, which also blurs it behind the panel, and glow. */
  image?: ArtemisCtaImage;
  /** Photos floating at the sides. floating-gallery: up to six, in pairs from the top, left then right; under 768px wide only the first two show. */
  images?: ArtemisCtaImage[];
  /** Faces in a row above the words. proof-orbit: up to five, from the left; the third is the largest. */
  avatars?: ArtemisCtaImage[];
  /** What the row of faces shows, read by screen readers. proof-orbit. Left out, it keeps the layout's own only when `avatars` is left out too. */
  avatarsLabel?: string;
  /** Figures under the buttons. floating-gallery; four look best. */
  stats?: ArtemisCtaStat[];
  /** Short facts along the foot of the panel. glow. */
  highlights?: string[];
  /** An install command with a copy button. terminal types it out; split shows it on its button. */
  command?: string;
  /** The lines the terminal prints after `command`. terminal. Left out, it keeps the layout's own lines only when `command` is left out too. */
  commandOutput?: string[];
  /** Questions with answers that open one at a time; the first starts open. faq. */
  questions?: ArtemisCtaQuestion[];
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, type TargetAndTransition, type Transition, useInView } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { useArtemisReduceAfterHydration } from "../../../lib/use-reduce-after-hydration";
import type { ArtemisCtaContent } from "../content";
const DEFAULT = {
    badge: "Ship in seconds",
    headline: "One command.",
    headlineAccent: "Production-ready UI.",
    subhead: "Pull premium, animated components straight into your app from the Artemis registry \u2014 no boilerplate, no config.",
    command: "npx zeus-ui add artemis-agent-chat-input",
    commandOutput: [
        "Resolving items from the Artemis registry\u2026",
        "Added chat-input \u00B7 message-stream \u00B7 tool-call",
        "Installed 3 components in 1.2s",
    ],
    cta: { label: "Get your license", href: "#" },
    secondaryCta: { label: "Browse components", href: "#" },
} satisfies ArtemisCtaContent;
const TICK_MS = 32;
const FIRST_LINE_MS = 450;
const LINE_MS = 300;
const HOLD_MS = 2800;
const COPIED_MS = 1600;
const BLOCK_HIDDEN: TargetAndTransition = { opacity: 0, y: 16, filter: "blur(6px)" };
const BLOCK_SHOWN: TargetAndTransition = { opacity: 1, y: 0, filter: "blur(0px)" };
const IN_VIEW_ONCE = { once: true, margin: "-56px" } as const;
const block = (delay: number): Transition => ({ duration: 0.6, delay, ease: ARTEMIS_EASE_OUT });
const word = (i: number): Transition => ({
    type: "spring",
    stiffness: 120,
    damping: 22,
    delay: i * 0.09,
    opacity: { duration: 0.7, delay: i * 0.09, ease: ARTEMIS_EASE_OUT },
    filter: { duration: 0.9, delay: i * 0.09, ease: ARTEMIS_EASE_OUT },
});
const LINE_TRANSITION: Transition = { duration: 0.3, ease: ARTEMIS_EASE_OUT };
const CARET_TRANSITION: Transition = { duration: 0.9, ease: "linear", times: [0, 1 / 3, 2 / 3, 1], repeat: Infinity };
const SWAP_TRANSITION: Transition = { duration: 0.18, ease: ARTEMIS_EASE_OUT };
const PRESS = { whileHover: { scale: 1.01 }, whileTap: { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS } as const;
const INSTANT: Transition = { duration: 0 };
const CheckIcon = ({ className }: {
    className: string;
}) => (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className} aria-hidden="true">
    <path d="M20 6 9 17l-5-5"/>
  </svg>);
export default function CtaSectionsTerminal({ content }: { content?: Partial<ArtemisCtaContent> } = {}) {
    const words = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? words.headlineAccent : content.headlineAccent;
    const output = content?.command === undefined ? words.commandOutput : content.commandOutput ?? [];
    const reduce = useArtemisReduceAfterHydration();
    return <TerminalCta key={reduce ? "reduce" : "motion"} reduce={reduce} words={words} accent={accent} output={output}/>;
}
function TerminalCta({ reduce, words, accent, output }: {
    reduce: boolean;
    words: typeof DEFAULT;
    accent?: string;
    output: string[];
}) {
    const command = words.command;
    const lines = output.length;
    const heading = (accent ? [words.headline, accent] : [words.headline]).map((line) => line.split(/\s+/).filter(Boolean));
    const rootRef = useRef<HTMLDivElement>(null);
    const inView = useInView(rootRef);
    const [count, setCount] = useState(command.length);
    const [step, setStep] = useState(lines);
    const [copied, setCopied] = useState(false);
    useEffect(() => {
        if (!inView || reduce) {
            setCount(command.length);
            setStep(lines);
            return;
        }
        let c = 1;
        let s = 0;
        let id: ReturnType<typeof setTimeout> | undefined;
        const run = () => {
            if (c <= command.length)
                id = setTimeout(() => {
                    c += 1;
                    setCount(c);
                    run();
                }, TICK_MS);
            else if (s < lines + 1)
                id = setTimeout(() => {
                    s += 1;
                    setStep(s);
                    run();
                }, s === 0 ? FIRST_LINE_MS : LINE_MS);
            else
                id = setTimeout(() => {
                    c = 1;
                    s = 0;
                    setCount(1);
                    setStep(0);
                    run();
                }, HOLD_MS);
        };
        setCount(1);
        setStep(0);
        run();
        return () => clearTimeout(id);
    }, [inView, reduce, command, lines]);
    useEffect(() => {
        if (!copied)
            return;
        const id = setTimeout(() => setCopied(false), COPIED_MS);
        return () => clearTimeout(id);
    }, [copied]);
    const copy = () => {
        navigator.clipboard?.writeText(command).then(() => setCopied(true), () => undefined);
    };
    const typing = count < command.length;
    let w = 0;
    return (<>
      <div className="art:w-full" ref={rootRef}>
        <section className="art:w-full art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:relative art:mx-auto art:flex art:w-full art:max-w-3xl art:flex-col art:items-center art:text-center">
            <motion.span className="art:inline-flex art:items-center art:rounded-full art:border art:border-border art:bg-background/70 art:px-3 art:py-1 art:font-medium art:text-muted-foreground art:text-xs art:backdrop-blur" initial={reduce ? false : BLOCK_HIDDEN} whileInView={reduce ? undefined : BLOCK_SHOWN} viewport={IN_VIEW_ONCE} transition={block(0)}>
              {words.badge}
            </motion.span>
            <h2 className="art:block art:mt-5 art:max-w-2xl art:text-balance art:font-sans art:text-foreground art:text-4xl art:font-medium">
              {heading.map((line) => (<span className="art:block" key={line.join(" ")}>
                  {line.map((text, j) => {
                const i = w++;
                return (<motion.span key={j} className="art:inline-block art:will-change-transform" initial={reduce ? { opacity: 0 } : { opacity: 0, y: i % 2 === 0 ? 19.2 : 16, filter: "blur(10px)" }} animate={reduce ? { opacity: 1 } : { opacity: 1, y: 0, filter: "blur(0px)" }} transition={reduce ? INSTANT : word(i)}>
                        {text}
                        {j < line.length - 1 ? (<span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                            {"\u00A0"}
                          </span>) : null}
                      </motion.span>);
            })}
                </span>))}
            </h2>
            <motion.p className="art:mt-5 art:max-w-xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-7 art:@min-[640px]/artemis:text-base" initial={reduce ? false : BLOCK_HIDDEN} whileInView={reduce ? undefined : BLOCK_SHOWN} viewport={IN_VIEW_ONCE} transition={block(0.12)}>
              {words.subhead}
            </motion.p>
            <motion.div className="art:mt-9 art:w-full art:max-w-xl art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-foreground art:text-left art:text-background art:ring-1 art:ring-background/10" initial={reduce ? false : BLOCK_HIDDEN} whileInView={reduce ? undefined : BLOCK_SHOWN} viewport={IN_VIEW_ONCE} transition={block(0.2)}>
              <div className="art:flex art:items-center art:gap-2 art:border-background/10 art:border-b art:bg-background/5 art:px-4 art:py-3">
                <span className="art:size-3 art:rounded-full art:bg-background/35"/>
                <span className="art:size-3 art:rounded-full art:bg-background/35"/>
                <span className="art:size-3 art:rounded-full art:bg-background/35"/>
                <span className="art:ml-2 art:font-mono art:text-xs art:text-background/55">
                  {"~/app"}
                </span>
                <motion.button type="button" className="art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:hover:text-inherit art:ml-auto art:inline-flex art:items-center art:gap-1.5 art:border art:border-background/10 art:bg-background/5 art:px-2 art:py-1 art:font-medium art:text-xs art:text-background/70 art:transition-colors art:hover:bg-background/10 art:rounded-full" tabIndex={0} onClick={copy} {...(reduce ? {} : PRESS)}>
                  <AnimatePresence mode="wait" initial={false}>
                    {copied ? (<motion.span key="copied" className="art:inline-flex art:items-center art:gap-1.5 art:text-success" initial={{ opacity: 0, scale: 0.6 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.6 }} transition={reduce ? INSTANT : SWAP_TRANSITION}>
                        <CheckIcon className="art:lucide art:lucide-check art:size-3"/>
                        {"Copied"}
                      </motion.span>) : (<motion.span key="copy" className="art:inline-flex art:items-center art:gap-1.5" initial={{ opacity: 0, scale: 0.6 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.6 }} transition={reduce ? INSTANT : SWAP_TRANSITION}>
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-copy art:size-3" aria-hidden="true">
                          <rect width="14" height="14" x="8" y="8" rx="2" ry="2"/>
                          <path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/>
                        </svg>
                        {"Copy"}
                      </motion.span>)}
                  </AnimatePresence>
                </motion.button>
              </div>
              <div className="art:space-y-2 art:px-4 art:py-5 art:font-mono art:text-xs art:leading-relaxed art:@min-[640px]/artemis:px-5">
                <div className="art:flex art:items-start art:gap-2">
                  <span className="art:select-none art:text-accent">
                    {"$"}
                  </span>
                  <span className="art:text-background/90">
                    {command.slice(0, count)}
                    {typing ? (<motion.span className="art:ml-0.5 art:inline-block art:h-[1.05em] art:w-[2px] art:translate-y-[2px] art:bg-accent art:align-middle" initial={{ opacity: 1 }} animate={{ opacity: [1, 1, 0, 0] }} transition={CARET_TRANSITION}/>) : null}
                  </span>
                </div>
                {output.map((text, i) => (<motion.div key={text} className="art:flex art:items-start art:gap-2 art:text-background/55" initial={reduce ? false : { opacity: 0, y: 6 }} animate={step > i ? { opacity: 1, y: 0 } : { opacity: 0, y: 6 }} transition={LINE_TRANSITION}>
                    <CheckIcon className="art:lucide art:lucide-check art:mt-0.5 art:size-3.5 art:shrink-0 art:text-success"/>
                    <span>
                      {text}
                    </span>
                  </motion.div>))}
              </div>
            </motion.div>
            <motion.div className="art:mt-9 art:flex art:flex-wrap art:items-center art:justify-center art:gap-3" initial={reduce ? false : BLOCK_HIDDEN} whileInView={reduce ? undefined : BLOCK_SHOWN} viewport={IN_VIEW_ONCE} transition={block(0.28)}>
              <motion.a className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:px-7 art:h-9 art:rounded-full" href={words.cta.href} tabIndex={0} {...(reduce ? {} : PRESS)}>
                {words.cta.label}
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                  <path d="M5 12h14"/>
                  <path d="m12 5 7 7-7 7"/>
                </svg>
              </motion.a>
              <motion.a className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-card art:text-foreground art:hover:border-border art:gap-2 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:px-6 art:h-9 art:rounded-full" href={words.secondaryCta.href} tabIndex={0} {...(reduce ? {} : PRESS)}>
                {words.secondaryCta.label}
              </motion.a>
            </motion.div>
          </div>
        </section>
      </div>
    </>);
}
